const EXPECTED_TYPES = ["fraud_case.answered"];
// Verifica Ambar-Signature: t=<unix>,v1=<hex(hmac-sha256(secreto, t + "." + cuerpo))>.
// Se firma el cuerpo crudo: volver a serializar el JSON podría cambiar bytes y romper la firma.
// WEBHOOK_SIGNING_SECRET admite varios secretos separados por coma (rotación sin corte).
const crypto = require('crypto');
const item = $input.first();
const secrets = String($env.WEBHOOK_SIGNING_SECRET || '').split(',').map((s) => s.trim()).filter(Boolean);
const header = String((item.json.headers || {})['ambar-signature'] || '');

let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (err) {
  raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : '';
}

let t = NaN;
const v1 = [];
for (const part of header.split(',')) {
  const i = part.indexOf('=');
  if (i < 0) continue;
  const k = part.slice(0, i).trim();
  const v = part.slice(i + 1).trim();
  if (k === 't') t = Number(v);
  else if (k === 'v1' && /^[0-9a-f]{64}$/.test(v)) v1.push(v);
}

let valid = false;
let reason = 'MISMATCH';
const now = Math.floor(Date.now() / 1000);
if (secrets.length === 0) reason = 'NO_SECRET';
else if (!Number.isInteger(t) || v1.length === 0) reason = 'MALFORMED';
else if (Math.abs(now - t) > 300) reason = 'EXPIRED';
else {
  for (const secret of secrets) {
    const expected = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest();
    const match = v1.some((c) => {
      const given = Buffer.from(c, 'hex');
      return given.length === expected.length && crypto.timingSafeEqual(given, expected);
    });
    if (match) {
      valid = true;
      break;
    }
  }
}

let event = null;
if (valid) {
  try {
    event = JSON.parse(raw);
  } catch (err) {
    valid = false;
    reason = 'MALFORMED';
  }
}
if (valid && !EXPECTED_TYPES.includes(event.type)) {
  valid = false;
  reason = 'UNEXPECTED_TYPE';
}
return [{ json: { valid, reason: valid ? null : reason, event } }];

const fmt = (c) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(c / 100);
const e = $('Verificar firma').first().json.event;
const d = e.data;
const data = { account_id: d.account_id, entry_id: d.entry_id, fraud_case_id: d.fraud_case_id };
if (d.recognized) {
  return [{ json: { event_id: e.id, kind: 'SECURITY', account_id: d.account_id, title: 'Gracias por confirmar',
    body: `Marcamos como reconocida tu transferencia de ${fmt(d.amount)}.`, data } }];
}
return [{ json: { event_id: e.id, kind: 'ACCOUNT_FROZEN', account_id: d.account_id, title: 'Congelamos tu cuenta',
  body: `Por tu seguridad, tu cuenta no puede enviar dinero. Te contactaremos para revisar la transferencia de ${fmt(d.amount)}.`, data } }];

// Push por Expo. Por privacidad, el texto del push es genérico salvo PUSH_SHOW_DETAILS=true:
// en la pantalla bloqueada no se muestran montos. El detalle está en la bandeja de la app.
// Solo se envía cuando el aviso se creó en esta ejecución (created): un reintento no repite el push.
const enabled = String($env.PUSH_ENABLED || 'false') === 'true';
const details = String($env.PUSH_SHOW_DETAILS || 'false') === 'true';
const messages = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.created) continue;
  for (const to of r.push_tokens || []) {
    messages.push({
      to,
      title: details ? r.notification.title : 'Ámbar',
      body: details ? r.notification.body : 'Tienes un aviso nuevo. Abre la app para verlo.',
      data: { notification_id: r.notification.id, kind: r.notification.kind, ...r.notification.data },
      sound: 'default',
      priority: 'high',
    });
  }
}
return [{ json: { send: enabled && messages.length > 0, count: messages.length, messages } }];

const fmt = (c) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(c / 100);
// A operación solo le llegan ids y montos, nunca datos personales del cliente.
const d = $('Verificar firma').first().json.event.data;
const alert = !d.recognized && Boolean($env.OPS_WEBHOOK_URL);
const text = `🚨 Caso ${d.fraud_case_id}: el cliente NO reconoce una transferencia de ${fmt(d.amount)} ` +
  `(puntaje ${d.score}: ${(d.reasons || []).join(', ')}). Cuenta ${d.account_id} ${d.account_frozen ? 'congelada' : 'sin congelar (revisar)'}.`;
return [{ json: { alert, text } }];
